package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;
final class StorageCheckpoint {
 private static JSONObject cached;private static long cachedElapsed=-1;static synchronized JSONObject read(Context c)throws Exception{long elapsed=android.os.SystemClock.elapsedRealtime();if(cached!=null&&cachedElapsed>=0&&elapsed>=cachedElapsed&&elapsed-cachedElapsed<30000)return new JSONObject(cached.toString());int local=0,read=0,receipts=0,metadataUnknown=0;File[] files=RecorderPhotoStore.root(c).listFiles();if(files==null)throw new IOException("photo inventory unavailable");SharedPreferences gallery=c.getSharedPreferences("recorder_gallery_exports",0);for(File f:files)if(f.getName().matches("[0-9]{13}-[a-f0-9-]{36}\\.gcm")){local++;if(local<=2000){try{if(RecorderPhotoStore.metadata(f).optBoolean("readOverlay")){read++;if(!gallery.getString(f.getName(),"").isEmpty())receipts++;}}catch(Exception unreadable){metadataUnknown++;}}}cached=new JSONObject().put("phonePhotos",local).put("readPhotos",read).put("readGalleryReceipts",receipts).put("partial",local>2000||metadataUnknown>0);cachedElapsed=elapsed;return new JSONObject(cached.toString());}
 static String describe(JSONObject v){return (v.optBoolean("partial")?"一部メタデータは未集計です。以下のREAD件数は確認できた範囲です。\n":"")+"保存先ごとの確認（最大30秒前の集計）\nスマホのロキ：保存ファイル "+v.optInt("phonePhotos")+"枚（一覧の在庫数）\nREAD写真："+v.optInt("readPhotos")+"枚 / ギャラリー保存時の確認記録 "+v.optInt("readGalleryReceipts")+"枚\nギャラリーの現在の存在・後日の削除は未確認です。KEEP写真のギャラリー保存やPCへの保存をこの数から推定しません。\nグラス保存・録音区間・未転送分は下記の転送記録を別に確認してください。在庫数だけで全件保存済みとは判断しません。";}
 private StorageCheckpoint(){}
}
